  "❌ HİDRASYON TESTİNDEN KALDIN! ZEN maçı iptal etti. Ücret yok, itibar zedelendi.": "❌ YOU FAILED THE HYDRATION TEST! ZEN cancelled the fight. No purse, reputation damaged.",
