  "❌ Vücudun pes etti. 1,5 kilo fazlasın, dudakların çatlamış. Ücretinin %20’si gidiyor ve kondisyonun çöktü.": "❌ Your body gave out. 1.5 kg over, lips cracked. 20% of your purse is gone and your cardio is shot.",
