  "Ailenden biri. Güvenilir ama sektörü tanımıyor.": "Family. Trustworthy, but doesn't know the business.",
  "Selim Kaptan": "Captain Selim",
  "Bölgesel organizasyonlarla sıkı ilişkiler.": "Strong ties with regional promotions.",
  "Doğu Avrupa bağlantıları güçlü, sert pazarlıkçı.": "Strong Eastern European connections, a tough negotiator.",
  "Sponsorluk anlaşmalarında usta.": "A master of sponsorship deals.",
  "PFC ve ZEN ile doğrudan hat.": "A direct line to PFC and ZEN.",
  "Marty \"Mürekkep\" Feld": "Marty \"Ink\" Feld",
  "Kontratları mürekkebi kurumadan imzalatır.": "Gets contracts signed before the ink dries.",
