  "💉 Karanlık Bir Teklif": "💉 A Shady Offer",
  "{0}: “Bu kür seni {1} dövüş boyunca canavara çevirir. Testlerde çıkmaz… genelde.” Fiyatı {2}.\n\nKabul edersen vuruş, kondisyon, hız ve çene ciddi artar. Yakalanırsan 6 ay ile 2 yıl arası men, popülerlik kaybı ve sponsor iptali.": "{0}: “This cycle will turn you into a monster for {1} fights. It won't show up on tests… usually.” The price is {2}.\n\nIf you accept, your striking, cardio, speed and chin go way up. If you're caught: a 6-month to 2-year ban, lost popularity and cancelled sponsors.",
  "Kabul et": "Accept",
  "Federasyona ihbar et": "Report to the commission",
  "Kürü aldın. Aynada başka biri var. Sonraki {0} dövüşte çok güçlüsün… ama her dövüşten sonra test riski var.": "You took the cycle. There's someone else in the mirror. You're very strong for the next {0} fights… but every fight carries a testing risk.",
  "Kibarca reddettin. Temiz bir kariyer, huzurlu bir uyku.": "You politely declined. A clean career, a peaceful sleep.",
  "Federasyona ihbar ettin. Basın seni “temiz sporun sesi” ilan etti. Popülerlik +2.": "You reported it to the commission. The press called you “the voice of clean sport”. Popularity +2.",
  "💼 Sponsorluk Teklifi": "💼 Sponsorship Offer",
  "Bahis": "Betting",
  "\n\nAma bir bahis şirketi… Bazı taraftarların hoşuna gitmeyebilir.": "\n\nBut it's a betting company… Some fans might not like it.",
  "{0} seninle çalışmak istiyor. Şortunda logoları olacak, karşılığında {1} ödeyecekler.{2}": "{0} wants to work with you. Their logos will be on your shorts, and they'll pay you {1}.{2}",
  "Pazarlık yap (+%50 dene)": "Negotiate (try +50%)",
  " (Bazı taraftarlar tepkili: popülerlik -2)": " (Some fans are unhappy: popularity -2)",
  "{0} ile anlaştın. +{1}{2}": "You signed with {0}. +{1}{2}",
  "Sıkı pazarlık işe yaradı! +{0}": "Hard bargaining paid off! +{0}",
  "{0} masadan kalktı. \"Başka dövüşçüler de var.\"": "{0} walked away. \"There are other fighters.\"",
  "Teklifi reddettin. İmajın temiz kaldı.": "You declined the offer. Your image stays clean.",
  "Antrenmanda sparring partnerini uyuttuğun bir video 2 milyon izlendi. Yorumlar ikiye bölünmüş durumda. Ne paylaşırsın?": "A video of you knocking out your sparring partner hit 2 million views. The comments are split. What do you post?",
  "Sıklettekilere laf at": "Call out the division",
  "Mütevazı bir teşekkür yaz": "Write a humble thank-you",
  "Görmezden gel": "Ignore it",
  "Paylaşımın ortalığı yıktı. Rakipler cevap yazıyor, gazeteciler seni arıyor. Popülerlik +5.": "Your post blew up. Rivals are replying, journalists are calling. Popularity +5.",
  "Kibirli buldular. \"Önce bir kemer kazan\" yorumları ağır bastı. Popülerlik -3.": "They found it arrogant. \"Win a belt first\" comments took over. Popularity -3.",
  "Samimi mesajın sevildi. Popülerlik +2.": "Your heartfelt message was loved. Popularity +2.",
  "Hiçbir şey yazmadın. Video kendi kendine yayılmaya devam etti. Popülerlik +1.": "You didn't post anything. The video kept spreading on its own. Popularity +1.",
  "🏟️ Salon Değiştirme Fırsatı": "🏟️ A Chance to Switch Gyms",
  "{0} baş antrenörü {1} seni takımında görmek istiyor (kalite {2}/10). Davetli olduğun için geçiş ücreti yarı fiyat: {3}.\n\nŞu anki hocan {4} (kalite {5}/10) seni sıfırdan yetiştirdi.": "{0} head coach {1} wants you on their team (quality {2}/10). Since you're invited, the transfer fee is half price: {3}.\n\nYour current coach {4} (quality {5}/10) built you from scratch.",
  "Taşın": "Move",
  "Kal, sadakat önemli": "Stay, loyalty matters",
  "Paran yetmiyor ({0} gerekli). Fırsat kaçtı.": "You can't afford it ({0} needed). The opportunity is gone.",
  "Yeni evin: {0}. {1} telefonda sessizce \"Başarılar evlat\" dedi ve kapattı.": "Your new home: {0}. On the phone, {1} quietly said \"Good luck, kid\" and hung up.",
  "Kaldın. Hocan gözleri dolarak sarıldı. Sonraki kampta ekstra motivasyonla çalışacaksın.": "You stayed. Your coach hugged you with tears in their eyes. You'll train with extra motivation next camp.",
  "🤝 Menajer Teklifi": "🤝 Management Offer",
  "Menajer {0} (kalite {1}/10) seni temsil etmek istiyor. Tüm kazançlarından %{2} alacak. Karşılığında kontrat pazarlıkları ve sponsorluklar çok daha kolay olacak.": "Manager {0} (quality {1}/10) wants to represent you. They'll take {2}% of all your earnings. In return, contract negotiations and sponsorships will be much easier.",
  "Anlaş": "Sign",
  "Kendi işimi kendim yaparım": "I'll handle my own business",
  "{0} artık menajerin. İlk sözü: \"Bir daha asla ucuza dövüşmeyeceksin.\"": "{0} is now your manager. Their first words: \"You'll never fight cheap again.\"",
  "Tek başına devam ediyorsun. Kazancın tamamen senin, ama masada yalnızsın.": "You're going it alone. Your earnings are all yours, but you're alone at the table.",
  "🏠 Aileden Bir Telefon": "🏠 A Call From Home",
  "Kardeşin arıyor. Babanın ameliyatı var ve {0} lazım. Sesi titriyor.": "Your sibling is calling. Your father needs surgery and they need {0}. Their voice is shaking.",
  "Hepsini gönder": "Send all of it",
  "Yarısını gönder": "Send half",
  "Şu an yapamam": "I can't right now",
  "Parayı gönderdin. Ameliyat başarılı geçti. Babanın mesajı: \"Oğlumla gurur duyuyorum.\" Motivasyonun tavan.": "You sent the money. The surgery went well. Your father's message: \"I'm proud of you.\" Your motivation is through the roof.",
  "Yarısını gönderdin, gerisini akrabalar tamamladı. İçin rahat.": "You sent half, relatives covered the rest. Your conscience is clear.",
  "Yapamadığını söyledin. Telefonu kapattıktan sonra uzun süre tavana baktın. Motivasyon düştü.": "You said you couldn't. After hanging up you stared at the ceiling for a long time. Motivation dropped.",
  "🍾 Ünlüler Partisi": "🍾 Celebrity Party",
  "Bir rapçinin partisine davetlisin. Kameralar, ünlüler, sabaha kadar eğlence. Kampa iki hafta var.": "You're invited to a rapper's party. Cameras, celebrities, partying till dawn. Camp is two weeks away.",
  "Git, görün": "Go, be seen",
  "Kibarca reddet": "Politely decline",
  "Evde kaldın, erkenden yattın. Sıkıcı ama profesyonel.": "You stayed home and went to bed early. Boring but professional.",
  "Gece kontrolden çıktı: bir kavga videosu sızdı. Magazin manşetlerindesin. Popülerlik -4, sağlık -8.": "The night got out of control: a fight video leaked. You're in the tabloid headlines. Popularity -4, health -8.",
  "Ünlülerle fotoğrafların her yerde. Yeni bir kitleye ulaştın. Popülerlik +3.": "Your photos with celebrities are everywhere. You reached a new audience. Popularity +3.",
  "🏎️ Hayalindeki Araba": "🏎️ Your Dream Car",
