  "Al, bunu hak ettin": "Buy it, you've earned it",
  "Parayı biriktir": "Save the money",
  "Anahtarları aldın. Instagram paylaşımın patladı. Popülerlik +2. Banka hesabın ise ağlıyor.": "You got the keys. Your Instagram post blew up. Popularity +2. Your bank account is crying though.",
  "Parayı biriktirdin. Kariyer uzun, sakatlık bir anda gelir.": "You saved the money. Careers are long, injuries come out of nowhere.",
  "🥊 Sert Sparring": "🥊 Hard Sparring",
  "Salona gelen deneyimli bir veteran seninle sert sparring yapmak istiyor. Çok şey öğrenebilirsin, ama adam hiç yavaşlamıyor.": "An experienced veteran at the gym wants to spar hard with you. You could learn a lot, but they never slow down.",
  "Kabul et, sonuna kadar git": "Accept, go all the way",
  "Teknik sparring olsun de": "Ask for technical sparring",
  "Çok şey öğrendin (IQ +{0}), ama bedeli ağır: {1} ({2} hafta).": "You learned a lot (IQ +{0}), but at a heavy price: {1} ({2} weeks).",
  "Yıpratıcıydı ama paha biçilmez. IQ +{0}.": "Grueling but priceless. IQ +{0}.",
  "Kontrollü bir çalışma. Tecrübesinden faydalandın. IQ +{0}.": "A controlled session. You benefited from their experience. IQ +{0}.",
