  "\"Seni çözdü! Ritmi değiştir, başka bir şey göster.\"": "\"They figured you out! Change the rhythm, show something new.\"",
  "\"Aynı kaseti çalıyorsun. Onu şaşırt!\"": "\"You're playing the same tape. Surprise them!\"",
  "\"Aynı şeyi tekrar yaparsan seni okur. Onu şaşırt.\"": "\"Do the same thing again and they'll read you. Surprise them.\"",
  "\"Tahmin edilebilir olma. Karıştır.\"": "\"Don't be predictable. Mix it up.\"",
  "\"Nefesin gitmiş! Tempoyu düşür, akıllı dövüş.\"": "\"You're gassed! Slow the pace, fight smart.\"",
  "\"Ağzın açık nefes alıyorsun, sakin! Ayaklarını kullan.\"": "\"You're breathing through your mouth, calm down! Use your feet.\"",
  "\"Gazın bitiyor, enerjini doğru yerde harca.\"": "\"Your gas is running out, spend your energy wisely.\"",
  "\"O yoruldu! Şimdi bas, şimdi!\"": "\"They're tired! Press now, NOW!\"",
  "\"Elleri düştü, gördün mü? Şimdi zamanı!\"": "\"Their hands dropped, see that? Now's the time!\"",
  "\"Adam bitmek üzere. Tempoyu artır!\"": "\"They're about to break. Raise the pace!\"",
