  "Organizasyonun resmi hesabı seni “yılın transferi” diye paylaştı.": "The promotion's official account called you “the signing of the year”.",
  "{seri} maçtır kaybetmiyorum. Kim durduracak beni?": "I haven't lost in {seri} fights. Who's going to stop me?",
  "Seri devam ediyor. Sıklette beni durduracak kimse yok.": "The streak goes on. Nobody in this division can stop me.",
