  "{rakip} diye bir dövüşçü yok, sadece bir sonraki kurbanım var.": "There's no fighter called {rakip}, just my next victim.",
  "{rakip} hayranları, şimdiden mendilleri hazırlayın. 🤧": "{rakip} fans, get your tissues ready. 🤧",
  "{rakip}’in çenesi o kadar dayanıklı değil, herkes biliyor.": "{rakip}'s chin isn't that durable, everyone knows it.",
  "Kamera önünde herkes aslan. Kafes kapısı kapanınca görürüz {rakip}.": "Everyone's a lion in front of the camera. We'll see when the cage door closes, {rakip}.",
  "{rakip}, hazır ol. Kariyerinin en kötü gecesi yaklaşıyor.": "{rakip}, get ready. The worst night of your career is coming.",
  "Söylediklerimin arkasındayım: {rakip} bu maçı bitiremeyecek.": "I stand by my words: {rakip} won't finish this fight.",
  "{sampiyon}, kemerini hazırla. Geliyorum. 🏆": "{sampiyon}, get your belt ready. I'm coming. 🏆",
  "{sampiyon} benden kaçıyor. {org}, bu maçı yapın!": "{sampiyon} is running from me. {org}, make this fight!",
  "Sıklette kimse benimle dövüşmek istemiyor. Sıradaki kim? 👀": "Nobody in the division wants to fight me. Who's next? 👀",
  "{sampiyon}, tahtında rahat oturma. Sıra bende.": "{sampiyon}, don't get comfortable on that throne. I'm next.",
  "İlk 5’e giren herkese açık davet: kafeste görüşelim.": "Open invitation to anyone in the top 5: see you in the cage.",
  "{org}, bana bir şampiyonluk maçı borçlusunuz. Hak ettim.": "{org}, you owe me a title shot. I've earned it.",
  "Adımı unutmayın. Yakında o kemer bende olacak.": "Remember my name. Soon that belt will be mine.",
  "{rakip} gerçek bir savaşçı. Maç gecesi en iyi hâlimizle karşılaşacağız. 🤝": "{rakip} is a real warrior. We'll meet at our best on fight night. 🤝",
  "Rakibime saygım sonsuz. Ama kazanan ben olacağım.": "Endless respect for my opponent. But I'll be the one winning.",
  "{hoca} ve tüm takımıma teşekkürler. Bu yol tek başına yürünmez.": "Thanks to {hoca} and my whole team. Nobody walks this road alone.",
  "Sıklette herkes çok çalışıyor. Bu yüzden bu spor güzel.": "Everyone in the division works hard. That's what makes this sport beautiful.",
  "Yenildiğim her maç bana bir şey öğretti. Hepsine minnettarım.": "Every loss taught me something. I'm grateful for all of them.",
  "Rakiplerime saygı, taraftarlara sevgi. Gerisi kafeste. 🙏": "Respect to my opponents, love to the fans. The rest happens in the cage. 🙏",
  "{takipci} kişi! İnanılmaz. Her birinize teşekkür ederim. ❤️": "{takipci} people! Incredible. Thank you, every single one of you. ❤️",
  "Maç gecesi tribünler yine bizim olsun! Kim geliyor? 🙌": "Let's own the stands on fight night again! Who's coming? 🙌",
  "Bir taraftarım bugün bana el yazısı mektup verdi. Ağladım. 🥹": "A fan handed me a handwritten letter today. I cried. 🥹",
  "{memleket}, bu zafer senin için!": "{memleket}, this win is for you!",
  "Sorularınızı yazın, en iyilerini bu akşam cevaplayacağım. 👇": "Drop your questions, I'll answer the best ones tonight. 👇",
  "Bu yolculukta yanımda olan herkese: sizin sayenizde buradayım.": "To everyone who's been with me on this journey: I'm here because of you.",
  "Kimse sana inanmasa da sen kendine inan. 💯": "Believe in yourself even when nobody else does. 💯",
  "Ter antrenmanda akar ki kan kafeste akmasın.": "Sweat in training so you don't bleed in the cage.",
  "Düştüğün yer değil, kalktığın yer seni tanımlar.": "It's not where you fall, it's where you get up that defines you.",
  "Bugün acı, yarın zafer. 🔥": "Pain today, victory tomorrow. 🔥",
  "Yetenek başlatır, disiplin bitirir.": "Talent starts it, discipline finishes it.",
  "Her sabah aynı soru: bugün dünden daha iyi miyim?": "Same question every morning: am I better than yesterday?",
  "Kolay olsaydı herkes şampiyon olurdu.": "If it were easy, everyone would be a champion.",
  "Bugün dinlenme günü. Ailemle kahvaltı. Savaşçılar da insan. ❤️": "Rest day today. Breakfast with family. Warriors are human too. ❤️",
  "Yeni tatlı yasak listesi: hepsi. 🍰❌": "New forbidden dessert list: all of them. 🍰❌",
  "Bir kahve, biraz müzik, sonra tekrar salon. ☕🎧": "A coffee, some music, then back to the gym. ☕🎧",
  "Hayatımda iki şey var: kafes ve sevdiklerim.": "Two things in my life: the cage and my loved ones.",
  "{sponsor} ile yola devam! Teşekkürler ekip. 🤝": "Rolling on with {sponsor}! Thanks, team. 🤝",
  "Maç gecesi {sponsor} logosuyla kafesteyim. 💪": "In the cage on fight night with the {sponsor} logo. 💪",
  "{sponsor} ailesine katılmak gurur verici. Birlikte zirveye!": "Proud to join the {sponsor} family. To the top together!",
  "Soru: sıradaki maçımı nakavtla mı bitireyim, submission ile mi? 👇": "Question: should I finish my next fight by knockout or submission? 👇",
  "Sizce sıklette en tehlikeli isim kim? Yorumlara yazın.": "Who do you think is the most dangerous name in the division? Comment below.",
  "Tüm zamanların en iyisi kim sizce? Tartışalım. 🐐": "Who's the greatest of all time? Let's debate. 🐐",
  "Maç gecesi hangi şarkıyla çıkayım? Önerilere açığım. 🎵": "Which song should I walk out to on fight night? Open to suggestions. 🎵",
  "Hangi rakiple dövüşmemi istersiniz? En çok beğenilen yorumu {org}’a ileteceğim.": "Who do you want me to fight? I'll pass the most-liked comment on to {org}.",
