  "Bir galibiyet daha: {0}-{1}. Durmak yok.": "Another win: {0}-{1}. No stopping.",
  "{0}’e saygılar, zorlu bir maçtı. Ama bu gece benimdi. 🤝": "Respect to {0}, it was a tough fight. But tonight was mine. 🤝",
  "Yüzümde morluk, kalbimde zafer. Teşekkürler herkese! ❤️": "Bruises on my face, victory in my heart. Thank you all! ❤️",
  "Bu gece o daha iyiydi. Salona dönüyorum, daha güçlü geleceğim.": "They were better tonight. I'm going back to the gym, I'll come back stronger.",
  "{0}’i tebrik ederim. Rövanşı istiyorum. 🔁": "Congratulations to {0}. I want the rematch. 🔁",
  "Düştüm. Kalkacağım. Her zaman olduğu gibi.": "I fell. I'll get up. Like always.",
  "Hakem kararlarına saygı duyuyorum ama katılmıyorum. Devam. ✊": "I respect the judges' decisions but I don't agree. Moving on. ✊",
  "Mesajlarınız için teşekkürler. Bu yenilgi hikâyemin sonu değil.": "Thanks for your messages. This loss isn't the end of my story.",
  "Beraberlik kimseyi mutlu etmez. Rövanş olmalı!": "A draw makes nobody happy. There has to be a rematch!",
  "{0} ile işimiz bitmedi.": "{0} and I aren't done.",
