  "Karakterini Nasıl Kurarsın?": "How Do You Build Your Character?",
  "🌍 Uyruk: Antrenman imkânı başlangıç istatistiklerini, taraftar desteği başlangıç popülerliğini belirler. İlk salonun ve hocan da ülkene göre gelir.": "🌍 Nationality: training options set your starting stats, fan support sets your starting popularity. Your first gym and coach also depend on your country.",
  "🎂 Yaş (18-30): Genç başlarsan ham ama hızlı gelişirsin (×1.3). Yaşlı başlarsan güçlü başlarsın ama 32’den sonra hız ve çene düşmeye başlar. 41’de emeklilik kaçınılmazdır.": "🎂 Age (18-30): Start young and you're raw but grow fast (×1.3). Start older and you're stronger, but after 32 speed and chin start to decline. Retirement is inevitable at 41.",
  "⚖️ Sıklet: Hafif sıkletler hızlı ve dayanıklıdır, ağır sıkletler sert vurur ama çabuk yorulur.": "⚖️ Weight class: Lighter weights are fast and durable, heavyweights hit hard but tire quickly.",
  "🥋 Branş: En önemli seçim. Güçlü ve zayıf yönlerini, dolayısıyla nasıl dövüşeceğini belirler.": "🥋 Background: The most important choice. It sets your strengths and weaknesses, and therefore how you fight.",
  "📖 Hikâye: Kendin yazabilir ya da oyuna yazdırabilirsin.": "📖 Story: Write it yourself or let the game write it.",
  "🎲 Zar: Son adımda istatistiklerin zarla belirlenir. Beğenmezsen 2 kez yeniden atabilirsin.": "🎲 Dice: In the last step your stats are rolled. Don't like them? You can reroll twice.",
  "Gelişim Puanı": "Skill Points",
  "Kariyere 3 puanla başlarsın. Her antrenman kampı 1-3 puan verir (yoğunluk, yaş, kamp yeri, hoca ve kadro kalitesine bağlı). Kampın odak alanı ayrıca +1-3 gelişir.": "You start your career with 3 points. Every training camp gives 1-3 points (depending on intensity, age, camp location, coach and staff quality). The camp's focus area also improves by +1-3.",
  "Dövüşler de puan verir: galibiyet 2, bitiriş +1, bonus +1, kemer +1. Mağlubiyet ve beraberlik 1 puan.": "Fights give points too: win 2, finish +1, bonus +1, belt +1. Loss and draw 1 point.",
  "📅 Bir dövüş döngüsü (kamp + toparlanma) yaklaşık 90-100 gün sürer. Yılda 3-4 kez dövüşürsün; her karar önemli.": "📅 A fight cycle (camp + recovery) takes about 90-100 days. You fight 3-4 times a year; every decision matters.",
  "Puanı istediğin istatistiğe harcarsın. 50’ye kadar +1 için 1 puan, 70’e kadar 2, 85’e kadar 3, sonrası 4 puan gerekir.": "Spend points on any stat you like. Up to 50, +1 costs 1 point; up to 70, 2; up to 85, 3; after that, 4 points.",
  "Kamp sonunda tartıdan önce, dövüş sonrasında ya da Kariyer ekranındaki GELİŞİM sekmesinden harcayabilirsin.": "You can spend them before the weigh-in at the end of camp, after a fight, or in the DEVELOPMENT tab on the Career screen.",
  "Nasıl Oynanır?": "How to Play",
  "1️⃣ Rakip seç. Bölgesel aşamada sen seçersin, büyük organizasyonlarda rakibi organizasyon dayatır.": "1️⃣ Choose an opponent. In the regional stage you choose; in the major promotions the opponent is assigned.",
  "2️⃣ Kamp: odak alanı, oyun planı, yoğunluk, kilo verme ve basın toplantısı. Oyun planı rakibin zaafına denk gelirse kafeste büyük avantaj sağlar.": "2️⃣ Camp: focus area, game plan, intensity, weight cut and press conference. A game plan that targets the opponent's weakness gives a big advantage in the cage.",
  "3️⃣ Dövüş: her raunt taktik seçersin. Kritik anlarda (rakip sarsıldı, submission yakalandı) hızlı karar verirsin.": "3️⃣ Fight: pick a tactic every round. In critical moments (opponent rocked, submission caught) you make quick decisions.",
  "4️⃣ Sonrası: bonuslar, röportaj, sıralama, kontrat teklifleri ve dövüşler arası olaylar.": "4️⃣ After: bonuses, interview, rankings, contract offers and events between fights.",
  "🏆 Yol: Amatör → Bölgesel (CFC, Hexagon) → Büyük (PFC, ZEN, VIP) → DWCS veya kısa haber → UCC kemeri.": "🏆 The road: Amateur → Regional (CFC, Hexagon) → Major (PFC, ZEN, VIP) → DWCS or short notice → UCC belt.",
