  "Saat gece 02:14. Şehrin kenarında, tabelasının yarısı yanmayan bir spor salonu var.": "It's 2:14 AM. On the edge of the city there's a gym with half its sign burnt out.",
  "İçeride tek bir ampul yanıyor. Duvarda solmuş bir poster var: sekizgen bir kafes ve havaya kaldırılmış altın bir kemer.": "A single bulb is on inside. On the wall, a faded poster: an octagon cage and a golden belt held high.",
  "“Herkes kemeri ister. Pek azı yolu yürür.”": "“Everyone wants the belt. Few walk the road.”",
