  "{0} sokaklarından çıktı, {1} yılda kemere uzandı. Sıradaki kim?": "Came out of the streets of {0} and reached the belt in {1} years. Who's next?",
  "{0} karşısında: {1}.": "Against {0}: {1}.",
  "{0} sokaklarından çıktı; {1} yaşında {2} galibiyete ulaştı, {3} bitiriş.": "Came out of the streets of {0}; {2} wins and {3} finishes by age {1}.",
  "HOCAN · {0}": "YOUR COACH · {0}",
  "ANLADIM": "GOT IT",
  "İpuçlarını kapat": "Turn off tips",
  "Burası senin köşen": "This is your corner",
  "Üstte paran, sağlığın ve popülerliğin var. Hazır olduğunda “DÖVÜŞ AYARLA” ile rakibini seç. Aradaki haftalarda mağaza, sosyal medya ve gece hayatı seni bekliyor; ama unutma, her şeyin bir bedeli var.": "Your money, health and popularity are up top. When you're ready, pick your opponent with “SET UP A FIGHT”. In the weeks between, the shop, social media and nightlife are waiting; but remember, everything has a price.",
  "Gelişim puanları": "Skill points",
  "Kamplardan ve dövüşlerden puan kazanırsın, burada istatistiklerine dağıtırsın. 50’den sonra her artış pahalanır; zayıf yönünü kapatmak çoğu zaman daha akıllıcadır.": "You earn points from camps and fights and spend them on your stats here. Past 50, every point costs more; covering your weakness is usually the smarter move.",
  "Rakibini seç": "Pick your opponent",
  "Her rakibin gücü ve zayıf yönü yazıyor. Kolay rakip güvenlidir ama az kazandırır; riskli bir rakibi yenersen sıralamada büyük bir sıçrama yaparsın.": "Each opponent's power and weakness are listed. An easy opponent is safe but pays off little; beat a risky one and you'll make a big jump in the rankings.",
  "Kamp başlıyor": "Camp is starting",
  "Önce kampın süresini seç. Uzun kamp daha çok geliştirir ama pahalıdır ve yorar. Kamptan önceki boş haftalarda teknik çalışabilir, spar yapabilirsin.": "First choose how long your camp is. A long camp develops you more but costs more and wears you down. In the free weeks before camp you can drill technique and spar.",
  "Oyun planı": "Game plan",
  "Rakibin zayıf yönüne uyan plan, dövüşte etkisini ikiye katlar. Keşif raporuna bak ve planını ona göre seç.": "A plan that matches your opponent's weakness doubles its effect in the fight. Check the scouting report and choose your plan accordingly.",
  "Burun buruna": "Face to face",
  "Tartıdan sonra rakibinle yüz yüze geleceksin. Takındığın tavır onun moralini bozabilir ya da sana pahalıya patlayabilir.": "After the weigh-in you'll go face to face with your opponent. Your attitude can break their spirit or cost you dearly.",
  "Her raundun başında bir taktik seç, dövüş kendi akar. Rakip sarsıldığında ya da bir submission fırsatında hızlı karar vermen gerekir. Kondisyonunu izle: yorulursan her şey zorlaşır.": "Pick a tactic at the start of each round and the fight flows on its own. When your opponent is rocked or a submission opens up, you'll need to decide fast. Watch your cardio: once you're tired, everything gets harder.",
  "Dövüş bitti": "The fight is over",
  "Mikrofon sende: röportajdaki sözlerin popülerliğini etkiler. Kazandığın puanları GELİŞİM sekmesinde harca. Güzel bir galibiyet mi? Paylaş, herkes görsün!": "The mic is yours: what you say in the interview affects your popularity. Spend the points you earned in the DEVELOPMENT tab. A great win? Share it so everyone sees!",
  "Google Play’de ücretsiz": "Free on Google Play",
