  "🗡️ {0} maçtan sonra mikrofonu aldı: \"Bu daha başlangıç. Kafeste her karşılaştığımızda aynı sonuç olacak.\" Bu isim peşini kolay bırakmayacak: artık bir ezeli rakibin var.": "🗡️ {0} grabbed the mic after the fight: \"This is just the beginning. Every time we meet in the cage, it'll end the same way.\" This name won't let go easily: you now have a nemesis.",
  "{0} iyi dövüşçü ama bana göre değil. Ne zaman isterse tekrar.": "{0} is a good fighter, but not on my level. Anytime they want a rematch.",
  "🗡️ {0} kameralara konuştu: \"{1} yenilmez sanılıyor. O balonu ben patlatacağım.\" Yeni bir ezeli rakibin var.": "🗡️ {0} told the cameras: \"Everyone thinks {1} is unbeatable. I'm going to pop that bubble.\" You have a new nemesis.",
  "{0}, kaçamazsın. Sıra bende.": "{0}, you can't run. I'm next.",
  "{1} karşısında kazanmak mı? Onu ben de yenerdim. Asıl sınav benim, {0}.": "Beating {1}? I'd have beaten them too. I'm the real test, {0}.",
  "Herkes seni konuşuyor {0}. Ben hâlâ o geceyi hatırlıyorum. 😏": "Everyone's talking about you, {0}. I still remember that night. 😏",
  "Güzel galibiyet {0}. Ama bir gün yine karşılaşacağız.": "Nice win, {0}. But we'll meet again one day.",
  "{0} formda görünüyor. Ben de. Tarih verin.": "{0} looks sharp. So do I. Set the date.",
  "{1} bile seni yendi. Ben sana söylemiştim, {0}.": "Even {1} beat you. I told you, {0}.",
  "Kafeste yerin yok, {0}. Bunu en iyi ben biliyorum.": "You don't belong in the cage, {0}. Nobody knows that better than me.",
