  "Seni yenen dövüşçü. İntikam, taraftarı ve basını ateşler.": "The one who beat you. Revenge fires up the fans and the press.",
  "Bu dövüşçünün posteri odamda artık 🥊": "This fighter's poster is on my wall now 🥊",
