  "Salona gelen deneyimli bir veteran seninle sert sparring yapmak istiyor. Çok şey öğrenebilirsin, ama hiç yavaşlamıyor.": "An experienced veteran at the gym wants to spar hard with you. You could learn a lot, but they never slow down.",
  "Bu kafesin sahibi benim. Anlaşıldı mı?": "I own this cage. Got it?",
  "Omuzlarımda kemerler, taht yine benim!": "Belts on my shoulders, the throne is mine again!",
