  "🤝 Yeni Antrenman Ortağı": "🤝 A New Training Partner",
  "{0} adında genç ve aç bir dövüşçü salona geldi. Seninle antrenman yapmak, kampına girmek istiyor. Yetenekli ama onu pek tanımıyorsun.": "A young, hungry fighter named {0} showed up at the gym. They want to train with you and join your camp. Talented, but you barely know them.",
  "Kampına al": "Bring them into camp",
  "Mesafeli dur": "Keep your distance",
  "Nazikçe geri çevirdin. {0} başka bir salona gitti.": "You politely turned them down. {0} went to another gym.",
  "{0} kampına katıldı. Sparringler sert ve verimli: IQ +1.": "{0} joined your camp. The sparring is hard and productive: IQ +1.",
  "🐍 Sırtından Bıçak": "🐍 A Knife in the Back",
  "{0} sessizce salondan ayrıldı ve bir rakibinin kampına geçti. Oyun planlarını, zayıf yönlerini, her şeyi anlatıyor olabilir.": "{0} quietly left the gym and joined a rival's camp. They could be spilling your game plans, your weaknesses, everything.",
  "Kampı baştan kur ({0})": "Rebuild the camp ({0})",
  "Basına anlat": "Tell the press",
  "Önemseme": "Ignore it",
  "Yeni bir sistem kurdun, bütün kombinasyonları değiştirdin. Masraflı ama sürpriz yine sende: IQ +1.": "You built a new system and changed every combination. Expensive, but the surprise is still yours: IQ +1.",
  "📰 İhanet: {0}, {1} ile yollarını ayırıp rakip kampa geçti.": "📰 Betrayal: {0} split with {1} and moved to a rival camp.",
  "Hikâyeni herkes konuştu. Taraftar senin yanında: popülerlik +3.": "Everyone's talking about your story. The fans are on your side: popularity +3.",
  "Önemsemedin; bu öfkeyi antrenmana taşıdın. Sonraki kampta motivasyon +1.": "You ignored it and took the anger into training. Motivation +1 next camp.",
  "📱 Bir Özür Mesajı": "📱 An Apology",
  "{0} yazdı: “Hata yaptım. O kampta anlatılanların hepsi boş çıktı. Geri dönebilir miyim?”": "{0} wrote: “I made a mistake. Everything they promised in that camp was empty. Can I come back?”",
  "Affet, geri al": "Forgive them, take them back",
  "Kapıyı kapat": "Close the door",
  "{0} geri döndü ve eskisinden sıkı çalışıyor. Kondisyon +1.": "{0} came back and is working harder than ever. Cardio +1.",
  "“Sadakat her şeydir.” Cevabın kısa ve netti. Popülerlik +1.": "“Loyalty is everything.” Your answer was short and clear. Popularity +1.",
  "🏥 Kritik Karar": "🏥 A Critical Decision",
  "{0} ciddi görünüyor ({1} hafta). Doktorun iki yol sunuyor: ameliyat ya da uzun fizik tedavi. Hocan ise “ağrı kesiciyle devam, zaman kaybetme” diyor.": "{0} looks serious ({1} weeks). Your doctor offers two paths: surgery or long physical therapy. Your coach says “take painkillers and keep going, don't waste time.”",
  "Ameliyat ({0})": "Surgery ({0})",
  "Fizik tedavi ({0})": "Physical therapy ({0})",
  "Ağrı kesiciyle devam": "Push on with painkillers",
  "Sakatlık kendiliğinden toparlandı.": "The injury healed on its own.",
  "Ameliyat başarılı geçti. İyileşme {0} hafta kısaldı.": "The surgery went well. Recovery is {0} weeks shorter.",
  "Uzun ve sabır isteyen bir süreç başladı. İyileşme 2 hafta kısaldı.": "A long process that takes patience has begun. Recovery is 2 weeks shorter.",
  "Ağrıyı bastırıp devam ettin. Hemen kafese dönebilirsin ama {0} kalıcı olarak -2.": "You masked the pain and pushed on. You can get back in the cage right away, but {0} is permanently -2.",
  "🔥 Geri Dönüş Hikâyesi": "🔥 A Comeback Story",
  "Sakatlıktan sonraki ilk galibiyetin manşetlerde: “Bitti denilen dövüşçü geri döndü!” Mikrofonlar sende.": "Your first win after the injury is in the headlines: “The fighter they wrote off is back!” The mic is yours.",
  "Ekibine teşekkür et": "Thank your team",
  "Eleştirenlere cevap ver": "Answer the critics",
  "🌧️ Zor Dönüş": "🌧️ A Tough Return",
  "Sakatlık sonrası dönüş istediğin gibi olmadı. Bazıları “eskisi gibi değil” diyor. {0}": "The comeback didn't go the way you wanted. Some say “they're not the same anymore.” {0}",
  "Ağrı kesicilerle geçen haftaların bedeli ağır.": "The weeks on painkillers are taking their toll.",
  "Daha çok çalış": "Work even harder",
  "Kendine zaman tanı": "Give yourself time",
  "Ekibinle kucaklaştığın fotoğraf haftanın en çok paylaşılanı oldu. Motivasyon +1.": "The photo of you hugging your team was the most shared of the week. Motivation +1.",
  "Sözlerin manşet oldu. Popülerlik +4.": "Your words made the headlines. Popularity +4.",
  "Sert çıkışın ters tepti; kibirli bulundun. Popülerlik -2.": "Your harsh response backfired; you came off as arrogant. Popularity -2.",
  "Salona herkesten önce gelip en son çıkıyorsun. +1 gelişim puanı.": "You're first into the gym and the last to leave. +1 skill point.",
  "Birkaç hafta aileyle, telefonsuz. Vücudun toparlandı: sağlık +20.": "A few weeks with family, no phone. Your body recovered: health +20.",
  "🧾 Muhasebeci Uyarıyor": "🧾 The Accountant's Warning",
  "Muhasebecin hesaplarda tutmayan rakamlar buldu. Menajerin {0} bazı ödemeleri kendi şirketi üzerinden geçiriyor olabilir.": "Your accountant found numbers that don't add up. Your manager {0} may be running some payments through their own company.",
  "Araştırt ({0})": "Investigate ({0})",
  "Menajerime güveniyorum": "I trust my manager",
  "Bir mali müşavir tuttun. Sonuçlar birkaç hafta içinde gelecek.": "You hired an auditor. The results will be in within a few weeks.",
  "Menajerine güvenmeyi seçtin. Muhasebeci omuz silkti.": "You chose to trust your manager. The accountant shrugged.",
  "⚖️ Gerçek Ortaya Çıktı": "⚖️ The Truth Comes Out",
  "Rapor net: {0} yıllar içinde senden {1} çekmiş. Ne yapacaksın?": "The report is clear: over the years {0} took {1} from you. What will you do?",
