  "Affet, devam et": "Forgive and move on",
  "💸 Hesap Boşaldı": "💸 The Account Is Empty",
  "{0} ortadan kayboldu, telefonları kapalı. Hesabından {1} eksik.": "{0} vanished and their phones are off. {1} is missing from your account.",
  "Yeni bir sayfa aç": "Start a new chapter",
  "📰 {0} menajeri tarafından dolandırıldı.": "📰 {0} was defrauded by their manager.",
  "Ders pahalıya patladı: -{0}. Artık menajerin yok.": "An expensive lesson: -{0}. You no longer have a manager.",
  "Mahkeme senden yana karar verdi: {0} geri geldi. Hikâyen herkese örnek oldu. Popülerlik +2.": "The court ruled in your favor: {0} came back. Your story became an example for everyone. Popularity +2.",
  "Sessiz bir anlaşma: {0} geri aldın ve yollarını ayırdın.": "A quiet settlement: you got {0} back and parted ways.",
  "Affettin. Menajerin minnettar ama ekipte bir şey kırıldı. Motivasyon -1.": "You forgave them. Your manager is grateful, but something broke in the team. Motivation -1.",
  "🥊 Babanın Hayali": "🥊 Your Father's Dream",
  "Baban gençliğinde amatör boksörmüş. Şimdi 58 yaşında, bir yardım gecesinde son bir kez ringe çıkmak istiyor. Senden destek bekliyor.": "Your father was an amateur boxer when he was young. Now he's 58 and wants to step into the ring one last time at a charity night. He's hoping for your support.",
  "Destekle, onu çalıştır": "Support him, train him",
  "Vazgeçirmeye çalış": "Try to talk him out of it",
  "Sabah koşularına artık baban da geliyor. Salonda herkes ona “Usta” diyor. Motivasyon +1.": "Your father joins your morning runs now. Everyone at the gym calls him “Master.” Motivation +1.",
  "Ona riskleri anlattın. Sessizce dinledi, bir şey demedi.": "You explained the risks. He listened quietly and said nothing.",
  "💔 Kırgın Bir Baba": "💔 A Hurt Father",
