  "{0} mi? Bu kafese değil, kreşe gitmeli.": "{0}? This one belongs in daycare, not the cage.",
  "Şu surata bakın: daha önce çok dayak yediği belli.": "Look at that face. You can tell it's taken plenty of beatings.",
  "Onun antrenmanlarını izledim. Annem daha sert vuruyor.": "I watched the training tapes. My mom hits harder.",
  "Tek yeteneği basın toplantısında uyumamak.": "The only talent here is staying awake at press conferences.",
  "Ben bu sıkletin kralıyım. Onu ilk rauntta uyutacağım, yazın bir kenara.": "I'm the king of this division. Lights out in round one, write it down.",
