  "Benim ısınmam onun bütün kariyeri kadar sürüyor.": "My warm-up lasts longer than this whole career.",
  "Hahaha! {0} titriyor bakın, ellerine bakın!": "Hahaha! {0} is shaking, look at those hands!",
  "Kilo verirken ağladığını duydum. Çok tatlı.": "Heard about the crying during the weight cut. So cute.",
  "Gözlerime bakamıyor bile. Daha şimdiden kaybetti.": "Can't even look me in the eye. Already lost.",
  "Hocası bile onun yerine utanıyor, şu hâline bakın.": "Even the coach is embarrassed. Just look at this.",
  "Kreş mi? Doğru, cumartesi seni orada bebek gibi uyutacağım.": "Daycare? Right, Saturday I'll put you to sleep like a baby.",
  "Annenle antrenman yapıyorsan bana da numarasını ver, belki bir şey öğrenirim.": "If you train with your mom, give me her number. Maybe I'll learn something.",
  "Konuş, konuş. Cumartesi gecesi konuşamayacaksın.": "Keep talking. Saturday night you won't be able to.",
  "Laflar ucuz. Kafeste görüşürüz.": "Talk is cheap. See you in the cage.",
  "Bir daha ağzını açarsan burada dağıtırım seni!": "Open your mouth again and I'll wreck you right here!",
